package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*; @Entity @Table(name="customer_profile") public class CustomerProfile {@Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="customer_profile_id") private UUID id; @Column(name="user_account_id",nullable=false,unique=true) private UUID userAccountId; @Column(name="date_of_birth") private LocalDate dateOfBirth; @Column(name="profile_status",nullable=false,length=30) private String profileStatus="ACTIVE"; @Column(name="reward_points_balance",nullable=false,precision=14,scale=2) private BigDecimal rewardPointsBalance=BigDecimal.ZERO; public CustomerProfile(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getUserAccountId(){return userAccountId;} public void setUserAccountId(UUID v){userAccountId=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getProfileStatus(){return profileStatus;} public void setProfileStatus(String v){profileStatus=v;} public BigDecimal getRewardPointsBalance(){return rewardPointsBalance;} public void setRewardPointsBalance(BigDecimal v){rewardPointsBalance=v;}}